package com.gnostica.modules.settings.service;
import com.gnostica.core.model.*; import com.gnostica.core.repository.*; import com.gnostica.core.util.PolicyHtmlSanitizer; import com.gnostica.modules.settings.dto.request.*; import com.gnostica.modules.settings.dto.response.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class TermService { private final TermRepository terms; private final TermModuleRepository modules;
 public List<TermModuleResponse> adminTree(){return tree(false);} public List<TermModuleResponse> publicTree(){return tree(true);} private List<TermModuleResponse> tree(boolean published){List<TermModule> ms=published?modules.findAllByStatusOrderBySortOrderAscTitleAsc(1):modules.findAllByOrderBySortOrderAscTitleAsc(); return ms.stream().map(m->TermModuleResponse.from(m,(published?terms.findAllByTermModuleIdAndStatusOrderBySortOrderAscTitleAsc(m.getId(),1):terms.findAllByTermModuleIdOrderBySortOrderAscTitleAsc(m.getId())).stream().map(TermResponse::from).toList())).toList();}
 public TermResponse publicTerm(String path){return terms.findByUrlPathAndStatus(path,1).map(TermResponse::from).orElseThrow(()->new IllegalArgumentException("Không tìm thấy điều khoản"));}
 @Transactional public TermModuleResponse createModule(TermModuleRequest r){TermModule m=new TermModule(); apply(m,r); return TermModuleResponse.from(modules.save(m),List.of());} @Transactional public TermModuleResponse updateModule(Integer id,TermModuleRequest r){TermModule m=modules.findById(id).orElseThrow(()->new IllegalArgumentException("Không tìm thấy mục"));apply(m,r);return TermModuleResponse.from(modules.save(m),List.of());} @Transactional public void deleteModule(Integer id){if(terms.existsByTermModuleId(id))throw new IllegalArgumentException("Hãy xóa hoặc chuyển các trang con trước");modules.deleteById(id);}
 @Transactional public TermResponse createTerm(TermRequest r){if(terms.findByUrlPath(r.getUrlPath()).isPresent())throw new IllegalArgumentException("Đường dẫn URL đã tồn tại");Term t=new Term();apply(t,r);return TermResponse.from(terms.save(t));} @Transactional public TermResponse updateTerm(Integer id,TermRequest r){Term t=terms.findById(id).orElseThrow(()->new IllegalArgumentException("Không tìm thấy điều khoản"));terms.findByUrlPath(r.getUrlPath()).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new IllegalArgumentException("Đường dẫn URL đã tồn tại");});apply(t,r);return TermResponse.from(terms.save(t));} @Transactional public void deleteTerm(Integer id){terms.deleteById(id);}
 private void apply(TermModule m,TermModuleRequest r){m.setTitle(r.getTitle().trim());m.setSortOrder(r.getSortOrder());m.setStatus(r.getStatus());m.setMetadata(r.getMetadata()==null?new LinkedHashMap<>():new LinkedHashMap<>(r.getMetadata()));} private void apply(Term t,TermRequest r){t.setTermModule(modules.findById(r.getTermModuleId()).orElseThrow(()->new IllegalArgumentException("Không tìm thấy mục")));t.setTitle(r.getTitle().trim());t.setUrlPath(r.getUrlPath().trim().toLowerCase());t.setContent(PolicyHtmlSanitizer.sanitize(r.getContent()));t.setSortOrder(r.getSortOrder());t.setStatus(r.getStatus());t.setMetadata(r.getMetadata()==null?new LinkedHashMap<>():new LinkedHashMap<>(r.getMetadata()));}}
